const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);

const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;
const TAU = Math.PI * 2;
const RINGS = [0.25, 0.5, 0.75, 1];

const THEMES = {
  dark: {
    bg: "#0A0A0B",
    fg: "#F3F2EF",
