  ...Interactive.baseSchema,
  theme: {
    type: "enum",
    default: "dark",
    variants: {
      dark: {},
      light: {},
    },
    description: "Theme",
  },
  brandLabel: {
    type: "text-content",
    default: "remocn",
    description: "Brand label",
  },
  competitorLabel: {
    type: "text-content",
    default: "Kitebase",
    description: "Competitor label",
  },
  stagger: {
    type: "number",
    default: 1.8,
    min: 0,
    max: 6,
    step: 0.2,
    description: "Vertex stagger",
    hiddenFromList: false,
  },
  rings: {
    type: "number",
    default: 4,
    min: 1,
    max: 8,
    step: 1,
    description: "Rings",
    hiddenFromList: false,
  },
  accent: {
    type: "color",
    default: "#3B5BFD",
    description: "Accent",
  },
  fontFamily: {
    type: "font-family",
    default: "Instrument Sans",
    description: "Font",
  },
  ink: {
    type: "color",
    default: undefined,
    description: "Text color",
  },
  background: {
    type: "color",
    default: undefined,
    description: "Background",
  },
  scale: {
    type: "number",
    default: 1,
    min: 0.5,
    max: 1.5,
